// 1. BASE DE DATOS LOCAL (Para que no se borre nada al refrescar)
const DB_NAME = "BASARYPERFUMERIAXIMENA_Data";
window.db_BASARYPERFUMERIAXIMENA = JSON.parse(localStorage.getItem(DB_NAME)) || { ventas: [], productos: [], gastos: [] };

window.saveDB = () => {
    localStorage.setItem(DB_NAME, JSON.stringify(window.db_BASARYPERFUMERIAXIMENA));
};

// 2. FUNCIÓN PARA AGREGAR PRODUCTOS CON ESPECIFICACIONES
window.registrarProductoPro = (nombre, precio, stock, specs) => {
    const nuevoProd = {
        id: Date.now(),
        nombre,
        precio: parseFloat(precio),
        stock: parseInt(stock),
        detalles: specs,
        fecha: new Date().toLocaleDateString()
    };
    window.db_BASARYPERFUMERIAXIMENA.productos.push(nuevoProd);
    window.saveDB();
    alert("✅ " + nombre + " registrado con éxito en el sistema.");
};

// 3. BUSCADOR INTELIGENTE (Para usar desde la consola o botones)
window.buscarProducto = (termino) => {
    const resultados = window.db_BASARYPERFUMERIAXIMENA.productos.filter(p => 
        p.nombre.toLowerCase().includes(termino.toLowerCase())
    );
    console.table(resultados);
    return resultados;
};

